#include "bench/VisualDensityBenchmark.hpp"
#include <algorithm>
#include <cmath>
#include <sstream>
namespace elysium::bench { namespace{std::uint64_t mix(std::uint64_t x){x^=x>>30;x*=0xbf58476d1ce4e5b9ULL;x^=x>>27;x*=0x94d049bb133111ebULL;return x^(x>>31);}double sane(double v){return std::isfinite(v)&&v>=0?std::min(v,4294967295.0):0;}} std::uint64_t fingerprint(SceneConfig c)noexcept{return mix(c.seed^std::uint64_t(c.version)*0x9e3779b97f4a7c15ULL^std::uint64_t(c.variant));} Capture sanitize(SceneConfig c,Capture x){x.sceneFingerprint=fingerprint(c);x.editVisibleMs=sane(x.editVisibleMs);x.generationMs=sane(x.generationMs);x.meshingMs=sane(x.meshingMs);x.frameMs=sane(x.frameMs);return x;} bool meaningPreserved(const Capture&x)noexcept{return x.landmarkVisible;} std::string report(const Capture&x){std::ostringstream o;o<<"fingerprint="<<x.sceneFingerprint<<" edit_visible_ms="<<x.editVisibleMs<<" generation_ms="<<x.generationMs<<" meshing_ms="<<x.meshingMs<<" frame_ms="<<x.frameMs<<" triangles="<<x.triangles<<" instances="<<x.instances<<" resident_bytes="<<x.residentBytes<<" queue="<<x.queueDepth<<" landmark="<<x.landmarkVisible<<" evidence="<<unsigned(x.evidence);return o.str();} }
